public static int calculateTimeNeeded(int N) {
    if (N <= 2)
        return 0;

    int time = 0;
    int n = N >> 1; // Equivalent to (N - 1) / 2 + 1 for odd numbers
    time += 2 * (n - 1); // Adding the time taken to move from the second person to the last person
    time += n; // Adding the time taken to move from the first person to the second person
    return time;
