import java.util.List;

public class Solution {
    public static List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> ans = new ArrayList<>();
        if (nums.length == 0)
            return ans;

        if (nums.length == 1) {
            ans.add(Arrays.asList(nums));
            return ans;
        }

        for (int i = 0; i < nums.length; i++) {
            int[] subArray = new int[nums.length - 1];
            for (int j = 0, k = 0; j < nums.length; j++) {
                if (j != i)
                    subArray[k++] = nums[j];
            }

            List<List<Integer>> permutations = permute(subArray);

            for (List<Integer> permutation : permutations) {
                List<Integer> newPermutation = new ArrayList<>();
                newPermutation.add(nums[i]);
                newPermutation.addAll(permutation);
                ans.add(newPermutation);
            }
        }

        return ans;
    }
}
