import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Permutations {
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> permutations = new ArrayList<>();
        if (nums == null || nums.length == 0) return permutations;
        permuteRecursive(nums, 0, permutations);
        return permutations;
    }

    private void permuteRecursive(int[] nums, int index, List<List<Integer>> permutations) {
        if (index == nums.length) {
            List<Integer> newPermutation = new ArrayList<>();
            for(int num : nums) newPermutation.add(num);
            permutations.add(newPermutation);
            return;
        }

        for (int i = index; i < nums.length; i++) {
            swap(nums, index, i);
            permuteRecursive(nums, index + 1, permutations);
            swap(nums, index, i); // backtrack to restore the original state
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
