public class Solution {
    public int findLargestSubstring(List<String> strings) {
        String maxSubstring = "";
        int maxIndex = 0;
        for (int i = 0; i < strings.size(); i++) {
            int index = strings.get(i).indexOf(maxSubstring);
            if (index != 0) {
                maxSubstring += strings.get(i).charAt(0);
                index = strings.get(i).indexOf(maxSubstring, index + 1);
                if (index != 0) {
                    maxSubstring += strings.get(i).charAt(0);
                } else {
                    maxSubstring += strings.get(i).charAt(index + 1);
                }
            } else {
                maxSubstring += strings.get(i).charAt(index + 1);
            }
            if (maxSubstring.length() > maxIndex) {
                maxIndex = maxSubstring.length();
            }
        }
        return maxIndex;
    }
}
