public boolean splitArraySameAverage(int[] nums) {
    int totalSum = Arrays.stream(nums).sum();
    if (totalSum % 2 != 0) return false;

    int targetSum = totalSum / 2;
    int[] prefixSum = new int[nums.length + 1];
    prefixSum[0] = 0;
    for (int i = 1; i <= nums.length; i++) {
        prefixSum[i] = prefixSum[i - 1] + nums[i - 1];
    }

    for (int i = 1; i < prefixSum.length; i++) {
        if (prefixSum[i] == targetSum) return true;

        if (prefixSum[i] - targetSum >= 0 && prefixSum[prefixSum.length - 1] - prefixSum[i] >= targetSum) {
            int leftSum = prefixSum[i] - targetSum;
            int remainingSum = prefixSum[prefixSum.length - 1] - leftSum;
            int[][] subarrays = splitArray(leftSum, remainingSum, i - 1);
            if (subarrays != null) return true;
        }
    }

    return false;
}

private int[][] splitArray(int leftSum, int remainingSum, int index) {
    if (leftSum < 0 || remainingSum < 0 || index < 0) {
        return null;
    }

    if (index == -1 && remainingSum == 0 && leftSum == 0) {
        return new int[][]{{}};
    }

    if (index > 0) {
        int[][] result = splitArray(leftSum, remainingSum, index - 1);
        if (result != null) {
            return result;
        }
    }

    if (index < nums.length - 1) {
        int[][] result = splitArray(leftSum + nums[index], remainingSum - nums[index], index + 1);
        if (result != null) {
            for (int[] subarray : result) {
                int[] newSubarray = IntArrays.merge(subarray, new int[]{nums[index]});
                result = addSubarray(result, newSubarray);
            }
            return result;
        }
    }

    return null;
}

private int[][] addSubarray(int[][] result, int[] subarray) {
    int[][] finalResult = new int[result.length + 1][subarray.length + 1];
    System.arraycopy(result, 0, finalResult, 0, result.length);
    finalResult[result.length] = subarray;
    return finalResult;
}
