public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = (int) Math.pow(2, k);
    boolean[] present = new boolean[m];
    for (int i = 0; i < n; i++) {
        if (i + k > n) break;
        int value = 0;
        for (int j = i; j < i + k; j++) {
            value = (value << 1) | s.charAt(j) - '0';
        }
        if (!present[value]) {
            present[value] = true;
