private int minFibonacciNumbersRecursive(int target, int[] fibs, Map<Integer, Integer> memo) {
    if (target == 0)
        return 0;
    if (target < 0)
        return Integer.MAX_VALUE;

    if (memo.containsKey(target))
        return memo.get(target);

    int minFib = Integer.MAX_VALUE;
    for (int fib : fibs) {
        if ( fib <= target) {
            minFib = Math.min(minFib, minFibonacciNumbersRecursive(target - fib, fibs, memo) + 1);
        }
    }

    memo.put(target, minFib);
    return memo.get(target);
}

private int[] generateFibonacciNumbers() {
    int[] fibs = new int[100];
    fibs[0] = 1;
    fibs[1] = 1;
    int index = 2;
    while (fibs[index - 1] + fibs[index - 2] <= 10000) {
        fibs[index] = fibs[index - 1] + fibs[index - 2];
        index++;
    }
    return fibs;
}
