private int maxUniqueSplit(String s, int index, Set<String> used, int length) {
    if (index == s.length() && length > 0) {
        return length;
    }

    int maxUnique = 0;
    for (int i = index; i < s.length(); i++) {
        String candidate = s.substring(index, i + 1);
        if (!used.contains(candidate)) {
            used.add(candidate);
            maxUnique = Math.max(maxUnique, maxUniqueSplit(s, i + 1, used, length + 1));
