public class SteppingNumberFinder {
    /**
     * Finds all stepping numbers in the range [low, high].
     *
     * @param low The lower bound of the range.
     * @param high The upper bound of the range.
     * @return A list of stepping numbers within the range [low, high] sorted in ascending order.
     */
    public static List<Integer> findSteppingNumbers(int low, int high) {
        Set<Integer> steppingNumbers = new LinkedHashSet<>();
        Stack<Integer> queue = new ArrayDeque<>();

        queue.push(0);
        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                steppingNumbers.add(num);
            }
            if (num < high) {
                processDigit(queue, num, 1, low, high);
                processDigit(queue, num, -1, low, high);
            }
        }

        List<Integer> sortedNumbers = new ArrayList<>(steppingNumbers);
        sortedNumbers.sort(Integer::compareTo);
        return sortedNumbers;
    }

    private static void processDigit(Stack<Integer> queue, int num, int direction, int low, int high) {
        int lastDigit = num % 10;
        int newDigit = lastDigit + direction;
        if (newDigit >= 0 && newDigit <= 9 &&
            newDigit >= lastDigit || newDigit + 9 <= lastDigit || newDigit - 9 >= lastDigit) {
            if (newDigit == low) {
                queue.push(num * 10 + newDigit);
            } else if (newDigit == high) {
                queue.addAll(Arrays.asList(num * 10 + newDigit, num * 10 + newDigit - 1, num * 10 + newDigit + 1));
            } else {
                queue.add(num * 10 + newDigit);
            }
        }
    }
}
