public int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int maxLen = 0;
    int[][] dp = new int[mat.length][mat[0].length];
    int[][] diags = new int[mat.length][ mat[0].length];
    int[][] antiDiags = new int[mat.length][mat[0].length];

    // Fill DP tables for horizontal and vertical lines
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                if (j > 0) dp[i][j] += dp[i][j - 1];
                if (i > 0) dp[i][j] += dp[i - 1][j];
            }
        }
    }

    // Fill DP tables for diagonal lines
    for (int i = 0; i <	mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                diags[i][j] = 1;
                if (i > 0 && j > 0) diags[i][j] += diags[i - 1][j - 1];
            }
        }
    }

    // Fill DP tables for anti-diagonal lines
    for (int i = 0; i < mat.length; i++) {
        for (int j = mat[0].length - 1; j >= 0; j--) {
            if (mat[i][j] == 1) {
                antiDiags[i][j] = 1;
                if (i > 0 && j < mat[0].length - 1) antiDiags[i][j] += antiDiags[i - 1][j + 1];
            }
        }
    }

    // Find the maximum length from all four directions
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            maxLen = Math.max(maxLen, Math.max(
                dp[i][j], Math.max(diags[i][j], antiDiags[i][j])
            ));
        }
    }

    return maxLen;
}
