private static void lexicalOrderUtil(int n, int current, ArrayList<Integer> result) {
    if (current > n)
        return;
    result.add(current);
    // Go to next set of digits in lexicographical order
    if (current * 10 <= n)
        lexicalOrderUtil(n, current * 10, result); // Next digit in same set
    else
        // Orthodox trick: backtracking to current with replaced last digit and next biggest
        if (current != 9)
            lexicalOrderUtil(n, current + 1, result); // Next digit in next set
}
